static inline int auth_parse ( struct sk_buff * skb , u8 * * challenge , int * chlen ) { struct ieee80211_authentication * a ; u8 * t ; if ( skb -> len < ( sizeof ( ieee80211_authentication ) - sizeof ( ieee80211_info_element ) ) ) { IEEE80211_DEBUG_MGMT ( "invalid len in auth resp: %d\n" , skb -> len ) ; return - EINVAL ; } * challenge = NULL ; a = ( ieee80211_authentication * ) skb -> data ; if ( skb -> len > ( sizeof ( ieee80211_authentication ) + 3 ) ) { t = skb -> data + sizeof ( ieee80211_authentication ) ; if ( * ( t ++ ) == MFIE_TYPE_CHALLENGE ) { * chlen = * ( t ++ ) ; * challenge = kmemdup ( t , * chlen , GFP_ATOMIC ) ; } } if ( a -> status ) { IEEE80211_DEBUG_MGMT ( "auth_parse() failed\n" ) ; return - EINVAL ; } return 0 ; } 